/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    int fantasyBooks = FTDBookTable::selectCountByGenre(FTDGenreEnum::Fantasy);
    int historyBooks = FTDBookTable::selectCountByGenre(FTDGenreEnum::HistoryNovel);
    int scienceBooks = FTDBookTable::selectCountByGenre(FTDGenreEnum::Science);

    Info(strFmt("@ITFormacion:NumberOfBooksByGenre", fantasyBooks, historyBooks, scienceBooks));
}
